# Disable NTFS Last Access Timestamp Write-Host "Disabling NTFS last access timestamp updates..." -ForegroundColor Cyan # Set NtfsDisableLastAccessUpdate to 1 (user managed) # 1 = Disable last access updates, 0x80000001 = User managed + disabled Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "NtfsDisableLastAccessUpdate" -Value 0x80000001 -Type DWord -Force -ErrorAction Stop Write-Host "NTFS last access timestamp updates have been disabled." -ForegroundColor Green Write-Host "Note: This takes effect for new file accesses. Existing timestamps are preserved." -ForegroundColor Yellow